//RC pass and change
//History:
//original:https://www.shadertoy.com/view/X33BzN
//fork1 (this sketch): https://www.shadertoy.com/view/XXdBWl
float TAU = 6.28318;

// Cycle through a color palette with a cosine wave
vec3 palette( float t ) {
    vec3 offset = vec3(0.3, 0.4, 0.2);
    vec3 amplitude = vec3(0.1, 0.1, 0.2);
    vec3 frequency = vec3(1.0, 1.0, 1.0);
    vec3 phase = vec3(0.263, 0.416, 0.557);

    return offset + amplitude * cos(TAU * (frequency * t + phase));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
     // Normalized pixel coordinates (from -1 to 1)
    // (-1,-1) = bottom left corner
    // (1,1) = top right corner
    vec2 uv = fragCoord / iResolution.xy * 2.0 - 1.0;

    // Default background color changes with time
    vec3 color = palette(0.1 * iTime);

    // Sine wave based on y coordinate
    if (uv.x < sin(uv.y + iTime)) {
        // Offset iTime so the color is different
        color = palette(iTime * 0.1 + 0.5);
    }

    // Sine wave based on x coordinate
    if (uv.y < sin(uv.x + iTime)) {
        // Offset iTime by a different amount
        color = palette(iTime * 0.1 + 0.2);
    }
    //lava circle thing:
    //compute distance from center (0, 0)
    float distFromCenter = length(uv)*abs(cos(iTime*0.1+uv.x*uv.y));

    //radius for annulus
    float radius = 0.3 +0.1*sin(iTime*0.3);  
    float radius2 = 0.25 +0.1*sin(iTime*0.3); 

    //if the fragment is within threshold(radius and radius2) bounds - invert the color
    if (distFromCenter < radius && distFromCenter > radius2) {
    //color inversion
        color = 1.0 - color;  
    }
    // -------------------------------------------------------------------

    // Output with an alpha of 1
    fragColor = vec4(color, 1);
}

vec2 mainSound(int samp, float time)
{
    // Define BPM and calculate the duration of each beat
    float bpm = 24.0;
    float beatDuration = 48.0 / bpm;  // 80 BPM means each beat is 0.75 seconds

    // Wrap the time within the total duration of the beat
    float loopTime = mod(time, beatDuration);

    // Create a triangle waveform for smooth forward and reverse morphing
    // The formula (abs(2.0 * (loopTime / beatDuration) - 1.0)) creates a triangle wave.
    float normalizedTime = abs(2.0 * (loopTime / beatDuration) - 1.0);

    // Frequencies for the G minor harmonic chord: G (392 Hz), Bb (466.16 Hz), D (587.33 Hz), F# (739.99 Hz)
    float freqG = 392.0;         // G note
    float freqBbMinor = 466.16;  // Bb note (minor third)
    float freqD = 587.33;        // D note (perfect fifth)
    float freqFSharp = 739.99;   // F# note (raised seventh)

    // Frequencies for the Bb major chord: Bb (466.16 Hz), D (587.33 Hz), F (698.46 Hz)
    float freqBbRoot = 466.16;   // Bb root note
    float freqDmajor = 587.33;   // D note (major third)
    float freqF = 698.46;        // F note (perfect fifth)

    // Interpolate each note of G minor into Bb major and back (linear interpolation)
    float currentFreq1 = mix(freqG, freqBbRoot, normalizedTime);        // Morph G to Bb root and back
    float currentFreq2 = mix(freqBbMinor, freqDmajor, normalizedTime);  // Morph Bb minor to D major and back
    float currentFreq3 = mix(freqD, freqF, normalizedTime);             // Morph D to F and back
    float currentFreq4 = mix(freqFSharp, freqDmajor, normalizedTime);   // Morph F# to D major and back (optional)

    // Generate sine waves for the morphed frequencies
    float sound1 = sin(6.2831 * currentFreq1 * loopTime) * exp(-3.0 * loopTime);
    float sound2 = sin(6.2831 * currentFreq2 * loopTime) * exp(-3.0 * loopTime);
    float sound3 = sin(6.2831 * currentFreq3 * loopTime) * exp(-3.0 * loopTime);
    float sound4 = sin(6.2831 * currentFreq4 * loopTime) * exp(-3.0 * loopTime);

    // Combine the four sounds for the morphing chord
    float chordMorph = (sound1 + sound2 + sound3 + sound4) / 4.0;

    // Frequencies for the low-end G minor chord: G (196.0 Hz), Bb (233.08 Hz), D (293.66 Hz)
    float freqGLow = 196.0;       // Low G root
    float freqBbLow = 233.08;     // Low Bb (minor third)
    float freqDLow = 293.66;      // Low D (perfect fifth)

    // Generate sine waves for the low-end G minor chord
    float lowG = sin(6.2831 * freqGLow * loopTime) * exp(-3.0 * loopTime);
    float lowBb = sin(6.2831 * freqBbLow * loopTime) * exp(-3.0 * loopTime);
    float lowD = sin(6.2831 * freqDLow * loopTime) * exp(-3.0 * loopTime);

    // Combine the low-end G minor chord
    float chordLowGminor = (lowG + lowBb + lowD) / 3.0;

    // Final sound: combine the morphing chord and the low-end G minor chord
    float finalSound = chordMorph + chordLowGminor * 0.5;  // Balance the low end

    return vec2(finalSound);  // Stereo output
}
